    summary:
      "Տոլման որոշվում է եղանակով, ոչ թե բաղադրատոմսով. բրինձը, սոխը և առատ կանաչին՝ աղացած գառան կամ տավարի մսով կամ առանց դրա, փաթաթվում է խաղողի կամ կաղամբի տերևի մեջ կամ լցվում միջուկը հանած պղպեղի, սմբուկի, լոլիկի ու սերկևիլի մեջ, ապա խիտ շարվում է կաթսայում, ծանրացվում և եփվում դանդաղ։ Անվանումը ծագում է թյուրքական բայից՝ «լցվել» իմաստով։ Անմիս տարբերակը՝ պասուց տոլման, պատրաստվում է լոբով, սիսեռով, ոսպով և հատիկեղենով, մատուցվում է սառը և պատկանում եկեղեցական պահքի օրերին։ Հայկական տներում այն հավաքույթների ուտեստ է, ոչ թե առօրյա ճաշ, և հարյուրավոր տերև փաթաթելը համատեղ աշխատանք է։ Եղանակը հին է և տարածված ողջ տարածաշրջանում՝ ազգակից անուններով. ՅՈՒՆԵՍԿՕ-ի 2017 թվականի ընդգրկումն արել է Ադրբեջանը և արձանագրում է կենդանի ավանդույթ, ոչ թե ծագում։",
    intro:
      "Տոլման բրնձի, սոխի, կանաչիի և հաճախ աղացած մսի լցոն է, որը փաթաթվում է տերևների մեջ կամ լցվում միջուկը հանած բանջարեղենի մեջ և եփվում դանդաղ։ Այն պատրաստվում է ողջ Կովկասում, Անատոլիայում, Իրանում և Արևելյան Միջերկրականում՝ նույն բայից ծագող անուններով։ Հայկական տներում այն հավաքույթների ուտեստ է, ոչ թե առօրյա արագ ճաշ, և ունի անմիս տարբերակ՝ պահքի համար։ 2017 թվականին ՅՈՒՆԵՍԿՕ-ն Ներկայացուցչական ցանկում ընդգրկեց տոլմա պատրաստելու ավանդույթը. այդ ներկայացումն արել է Ադրբեջանը, և փաստը նշվում է այստեղ, այլ ոչ թե շրջանցվում, որովհետև այդ ընդգրկման ընթերցումն ինքն այս ուտեստի պատմության մասն է։",
