    summary:
      "Գաթան անուշ թխվածք է, որի լցոնն ունի սեփական անուն՝ խորիզ. կարագի ու շաքարի մեջ շփված ալյուր, որը փշրանքներով է պահվում և թխվելիս հետ է հալվում խմորի մեջ։ Խմորը հարստացվում է կարագով, հաճախ նաև մածունով կամ թթվասերով, իսկ վերևը թխելուց առաջ քսվում է ձվով և նախշվում. զարդարանքը միաժամանակ խանգարում է մակերևույթին ուռչել։ Արդյունքը խոնավ չէ, այլ չոր, և հենց դա է թույլ տալիս գաթային պահվել ու ճանապարհ գնալ. ամբողջական, փաթաթված գաթան այցելության սովորական նվերն է, իսկ վանքերի դարպասների մոտ վաճառվող նախշված շրջանները շատերի հիշողության մեջ գաթայի հիմնական տեսքն են։ Մնացած գրեթե ամեն ինչ փոփոխական է. չափերը՝ սեղանի լայնությամբ շրջանից մինչև ափի մեջ տեղավորվող գլանիկ, շատ ընտանիքներ պահում են իրենց նախշը, իսկ ընկույզով տարբերակը, որ պատրաստվում է հարավում և Իրանի հայերի մոտ, հաճախ կոչվում է նազուկ։",
